/* prog22_snake_camel_convert.c
 *
 * The original binary implements a tiny command‑line utility that converts
 * between snake_case and camelCase strings.  The control flow is heavily
 * obfuscated, but the observable behaviour is simple:
 *
 *   prog22_snake_camel_convert to_camel  <snake_string>
 *   prog22_snake_camel_convert to_snake  <camelString>
 *
 * If the number of arguments is not exactly three the program prints
 *   USAGE
 * and exits.  If the first argument is neither “to_camel” nor “to_snake”
 * the program prints
 *   INVALID_MODE
 * and exits.  Otherwise it prints the converted string (followed by a
 * newline) using `puts`.
 *
 * The original binary limits the output buffer to 1024 bytes; the
 * re‑implementation respects the same limit.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_MAX 1024

static char main_out[OUT_MAX];

/* Convert a snake_case string to camelCase.
 *   "hello_world" -> "helloWorld"
 *   "a_b_c"        -> "aBC"
 *   leading/trailing '_' are ignored.
 */
static void to_camel(const char *src)
{
    size_t out_i = 0;
    int capitalize_next = 0;

    for (size_t i = 0; src[i] != '\0' && out_i + 1 < OUT_MAX; ++i) {
        char c = src[i];

        if (c == '_') {
            /* remember that the next alphabetic character must be upper‑cased */
            capitalize_next = 1;
            continue;
        }

        if (capitalize_next && isalpha((unsigned char)c)) {
            c = (char)toupper((unsigned char)c);
            capitalize_next = 0;
        }

        main_out[out_i++] = c;
    }
    main_out[out_i] = '\0';
}

/* Convert a camelCase string to snake_case.
 *   "helloWorld" -> "hello_world"
 *   "ABC"        -> "a_b_c"
 *   Upper‑case letters are lower‑cased and preceded by '_' (except at the
 *   very start of the output).
 */
static void to_snake(const char *src)
{
    size_t out_i = 0;

    for (size_t i = 0; src[i] != '\0' && out_i + 2 < OUT_MAX; ++i) {
        unsigned char c = (unsigned char)src[i];

        if (isupper(c)) {
            /* insert '_' before the lower‑cased character unless we are at
               the very beginning of the output */
            if (out_i != 0) {
                main_out[out_i++] = '_';
            }
            c = (unsigned char)tolower(c);
        }
        main_out[out_i++] = (char)c;
    }
    main_out[out_i] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }

    if (strcmp(argv[1], "to_camel") == 0) {
        to_camel(argv[2]);
        puts(main_out);
    } else if (strcmp(argv[1], "to_snake") == 0) {
        to_snake(argv[2]);
        puts(main_out);
    } else {
        puts("INVALID_MODE");
    }

    return 0;
}
